const express = require("express");
const { requestLogger } = require("./logging");
const { sessionUser } = require("./auth");
const accounts = require("./routes/accounts");
const orders = require("./routes/orders");

const app = express();
app.use(express.json());

// Logs every request, including ones sessionUser rejects, so it goes before
// the auth middleware.
app.use(requestLogger);

// Resolves the session cookie to a user row and sets req.user for every
// request; requests without a valid session are rejected here.
app.use(sessionUser);

app.use("/accounts", accounts);
app.use("/orders", orders);

app.listen(process.env.PORT || 3000);

auth.js.text:
const db = require("./db");

// Resolves the session cookie to its user and account. Every request that
// reaches a route handler has passed through here.
async function sessionUser(req, res, next) {
  const rows = await db.query(
    `SELECT u.id, u.email, u.account_id
     FROM sessions s
     JOIN users u ON u.id = s.user_id
     JOIN accounts a ON a.id = u.account_id
     WHERE s.token = $1 AND s.expires_at > now() AND a.deleted_at IS NULL`,
    [req.cookies && req.cookies.session]
  );
  if (!rows.length) return res.status(401).end();
  req.user = { id: rows[0].id, email: rows[0].email, accountId: rows[0].account_id };
  next();
}

module.exports = { sessionUser };

logging.js.text:
// Logs one line per request after the response finishes, so it captures the
// final status code (including responses written by later middleware/routes)
// and requests that fail auth before reaching a route.
function requestLogger(req, res, next) {
  const start = Date.now();
  res.on("finish", () => {
    console.log(JSON.stringify({
      method: req.method,
      path: req.originalUrl,
      status: res.statusCode,
      ms: Date.now() - start,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
}

module.exports = { requestLogger };

