  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const result = await fn(client);
    await client.query("COMMIT");
    return result;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
```
which is just `write()` generalized to run arbitrary logic instead of one fixed query — worth having anyway for any future multi-statement write.

