  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 AND deleted_at IS NULL RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 AND deleted_at IS NULL RETURNING id",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.status(204).end();
});

module.exports = router;

routes/orders.js.text:
const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key") || null;

  // ON CONFLICT DO NOTHING makes this race-safe: if two requests with the
  // same key hit concurrently, the unique index lets exactly one insert
  // succeed and the other returns no row here instead of erroring.
  const row = await db.write(
    `INSERT INTO orders (account_id, sku, quantity, idempotency_key)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (account_id, idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING
     RETURNING *`,
    [req.user.accountId, req.body.sku, req.body.quantity, idempotencyKey]
  );

  if (row) return res.status(201).json(row);

  // Conflict: an order with this key already exists for this account.
  const existing = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );
  res.status(200).json(existing[0]);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

